import unittest

from alpha.farewell import farewell


class FarewellTest(unittest.TestCase):
    def test_farewell_text(self):
        self.assertEqual(farewell(), "goodbye, demo")

    def test_farewell_is_str_without_newline(self):
        text = farewell()
        self.assertIsInstance(text, str)
        self.assertFalse(text.endswith("\n"))
        self.assertEqual(len(text), 13)


if __name__ == "__main__":
    unittest.main()
